import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, Wire, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false); // Default to Paused
  const [tickSpeed, setTickSpeed] = useState(50); 

  // -- Multi-Circuit (Function) State --
  const [functions, setFunctions] = useState<FunctionCircuit[]>([
    { id: 'main', name: 'Main Circuit', components: [], wires: [] }
  ]);
  const [activeFunctionId, setActiveFunctionId] = useState<string>('main');

  // -- UI State --
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Selection State for Editing --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Helper to get active function data safely
  const activeFunction = functions.find(f => f.id === activeFunctionId) || functions[0];

  // -- Life Cycle --

  // Load from Local Storage on Mount
  useEffect(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setFunctions(parsed);
        }
      }
    } catch (e) {
      console.error("Failed to load autosave", e);
    }
  }, []);

  // -- Drag & Drop Logic --

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedType, x: relX, y: relY, functionId: draggedFuncId });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  // -- Data Management Logic --

  /**
   * Synchronously gathers the complete state of the project.
   * Merges the live Canvas state (ref) with the stored React state for other functions.
   */
  const getLatestFunctionsState = (): FunctionCircuit[] => {
    if (canvasRef.current) {
      const { components, wires } = canvasRef.current.getData();
      return functions.map(f => 
        f.id === activeFunctionId 
          ? { ...f, components: [...components], wires: [...wires] }
          : f
      );
    }
    return functions;
  };

  const saveCurrentState = () => {
    const updated = getLatestFunctionsState();
    setFunctions(updated);
    return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    saveCurrentState();
    setSelectedComponent(null);
    setActiveFunctionId(id);
    setIsPlaying(false); // Pause when switching context
  };

  // -- Storage / File Operations --

  const handleQuickSave = () => {
    const currentData = saveCurrentState();
    try {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(currentData));
      // Visual feedback could be added here
      alert("Project saved to browser storage.");
    } catch (e) {
      alert("Failed to save: Storage might be full.");
    }
    setIsProjectMenuOpen(false);
  };

  const handleClearStorage = () => {
    if (confirm("Clear local saved data? This will not delete the current workspace.")) {
        localStorage.removeItem(LOCAL_STORAGE_KEY);
    }
    setIsProjectMenuOpen(false);
  };

  const downloadJSON = (data: any, filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportProject = () => {
    const data = getLatestFunctionsState();
    downloadJSON(data, `logicflow_project_${new Date().getTime()}.json`);
    setIsProjectMenuOpen(false);
  };

  const handleExportFunction = () => {
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const funcData: FunctionCircuit = {
            ...activeFunction,
            components,
            wires
        };
        downloadJSON(funcData, `${activeFunction.name.replace(/\s+/g, '_')}_function.json`);
    }
    setIsProjectMenuOpen(false);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
    setIsProjectMenuOpen(false);
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content);

            if (Array.isArray(parsed)) {
                // CASE 1: Full Project Import
                // Simple validation check
                if (parsed.length > 0 && parsed[0].id && parsed[0].components) {
                    if (confirm("This will replace your current project. Continue?")) {
                        setFunctions(parsed);
                        setActiveFunctionId(parsed[0].id);
                        setSelectedComponent(null);
                        setIsPlaying(false);
                    }
                } else {
                    alert("Invalid Project File");
                }
            } else if (typeof parsed === 'object' && parsed.id && parsed.components) {
                // CASE 2: Single Function Import
                const newFunc = parsed as FunctionCircuit;
                // Avoid ID collision
                const existing = functions.find(f => f.id === newFunc.id);
                if (existing) {
                    newFunc.id = crypto.randomUUID();
                    newFunc.name = `${newFunc.name} (Imported)`;
                }

                saveCurrentState(); // Ensure current canvas is saved before state update
                setFunctions(prev => [...prev, newFunc]);
                alert(`Imported function: ${newFunc.name}`);
                // Optional: Switch to it?
                // setActiveFunctionId(newFunc.id);
            } else {
                alert("Unknown file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse JSON file.");
        }
        // Reset input
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  // -- Modal / Creation --

  const openNewFunctionModal = () => {
    setNewFuncName("");
    setIsModalOpen(true);
  };

  const submitNewFunction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFuncName.trim()) return;

    saveCurrentState();
    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = {
      id: newId,
      name: newFuncName,
      components: [],
      wires: []
    };
    setFunctions(prev => [...prev, newFunc]);
    setActiveFunctionId(newId);
    setIsModalOpen(false);
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') {
      alert("Cannot delete Main Circuit");
      return;
    }
    if (confirm("Are you sure you want to delete this function?")) {
      setFunctions(prev => prev.filter(f => f.id !== id));
      if (activeFunctionId === id) {
        setActiveFunctionId('main');
      }
    }
  };

  // -- Property Editor --

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) {
          setTempLabel(comp.customLabel || (comp.type === ComponentType.INPUT_SWITCH ? "IN" : (comp.type === ComponentType.OUTPUT_LED ? "OUT" : "")));
      } else {
        setTempLabel("");
      }
  };

  const updateLabel = (val: string) => {
      setTempLabel(val);
      updateComponentProp({ customLabel: val });
  };

  const updateComponentProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileImport} 
        accept=".json" 
        className="hidden" 
      />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => {
          if (t === 'SELECT' || t === 'DELETE') {
            setSelectedTool(t);
          }
        }}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">

        {/* Top Toolbar / HUD */}
        <div 
            className="absolute top-4 left-4 right-4 md:h-14 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap md:flex-nowrap items-center justify-between px-4 z-10 border border-slate-200 pointer-events-auto py-2 md:py-0 gap-2"
            onPointerDown={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            onTouchStart={(e) => e.stopPropagation()}
        >

          <div className="flex items-center space-x-2 md:space-x-4">
             {/* Function Selector */}
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => switchToFunction(e.target.value)}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => (
                   <option key={f.id} value={f.id}>{f.name}</option>
                 ))}
               </select>

               <button 
                 onClick={openNewFunctionModal}
                 className="ml-2 w-8 h-8 flex items-center justify-center bg-blue-100 text-blue-600 rounded hover:bg-blue-200 text-lg font-bold touch-manipulation"
                 title="New Function"
               >
                 +
               </button>

               {activeFunctionId !== 'main' && (
                 <button 
                   onClick={() => deleteFunction(activeFunctionId)}
                   className="ml-1 w-8 h-8 flex items-center justify-center bg-red-100 text-red-500 rounded hover:bg-red-200 text-lg font-bold touch-manipulation"
                   title="Delete Function"
                 >
                   ×
                 </button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             {/* Playback Controls */}
             <div className="flex items-center space-x-2 mr-2 hidden sm:flex">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500' : 'bg-slate-300'}`}></span>
             </div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors touch-manipulation"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             {/* Project / Storage Menu */}
             <div className="relative">
                <button
                    onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)}
                    className="flex items-center space-x-1 px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors"
                >
                    <span>Project</span>
                    <span className="text-xs">▼</span>
                </button>

                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <button onClick={handleQuickSave} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">💾</span> Quick Save (Browser)
                        </button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={triggerFileUpload} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📂</span> Import File...
                        </button>
                        <button onClick={handleExportProject} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📦</span> Export Project (All)
                        </button>
                        <button onClick={handleExportFunction} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📄</span> Export Function (Active)
                        </button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={handleClearStorage} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center">
                            <span className="mr-2">🗑️</span> Clear Browser Data
                        </button>
                    </div>
                )}
                {/* Backdrop to close menu */}
                {isProjectMenuOpen && (
                    <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>
                )}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {/* Property Editor (Visible when Selected) */}
             {selectedComponent && (
                 <div className="flex items-center space-x-2 mr-2 flex-1 md:flex-none justify-center">
                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <span className="text-[10px] font-bold text-yellow-600 mr-2 uppercase whitespace-nowrap">Label</span>
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => updateLabel(e.target.value)}
                            className="bg-white border border-yellow-200 text-base px-2 py-1 rounded w-24 md:w-32 focus:outline-none focus:border-yellow-400 shadow-sm select-text"
                            placeholder="Name..."
                        />
                     </div>

                     {/* IC Port Side Selector (Only for I/O) */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED || selectedComponent.type === ComponentType.CLOCK) && (
                         <div className="flex items-center bg-blue-50 px-2 py-1 rounded border border-blue-200">
                            <span className="text-[10px] font-bold text-blue-600 mr-2 uppercase whitespace-nowrap">Pin Side</span>
                            <select 
                                value={selectedComponent.icPortSide || (selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.CLOCK ? 'right' : 'left')}
                                onChange={(e) => updateComponentProp({ icPortSide: e.target.value as any })}
                                className="bg-white border border-blue-200 text-sm px-2 py-1 rounded w-20 focus:outline-none focus:border-blue-400 shadow-sm"
                            >
                                <option value="top">Top</option>
                                <option value="bottom">Bottom</option>
                                <option value="left">Left</option>
                                <option value="right">Right</option>
                            </select>
                         </div>
                     )}
                 </div>
             )}

            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider hidden sm:inline">DELAY</span>
            <input 
              type="range" 
              min="5" 
              max="1000" 
              step="5"
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-24 h-4 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-900 touch-pan-x" 
            />
            <span className="text-xs text-slate-500 w-8 text-right font-mono hidden sm:inline">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={activeFunctionId}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={handlePendingDropHandled}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {draggedType === ComponentType.CUSTOM_IC ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}
              </span>
            </div>
          </div>
        )}

        {/* Modal Overlay */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden" onPointerDown={(e) => e.stopPropagation()}>
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100">
                <h3 className="font-bold text-slate-700">Create New Function</h3>
              </div>
              <form onSubmit={submitNewFunction} className="p-4">
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Function Name</label>
                <input 
                  autoFocus
                  type="text" 
                  value={newFuncName}
                  onChange={(e) => setNewFuncName(e.target.value)}
                  placeholder="e.g. Full Adder"
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4 text-base font-semibold text-slate-700 select-text"
                />
                <div className="flex justify-end space-x-2">
                  <button 
                    type="button"
                    onClick={() => setIsModalOpen(false)}
                    className="px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-100 rounded-lg transition-colors"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="px-4 py-2 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors"
                  >
                    Create
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, Wire, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false); // Default to Paused
  const [tickSpeed, setTickSpeed] = useState(50); 

  // -- Multi-Circuit (Function) State --
  const [functions, setFunctions] = useState<FunctionCircuit[]>([
    { id: 'main', name: 'Main Circuit', components: [], wires: [] }
  ]);
  const [activeFunctionId, setActiveFunctionId] = useState<string>('main');

  // -- UI State --
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // -- Selection State for Editing --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Refs for Autosave (Access latest state in intervals/callbacks)
  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);

  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  // Helper to get active function data safely
  const activeFunction = functions.find(f => f.id === activeFunctionId) || functions[0];

  // -- Life Cycle --

  // Load from Local Storage on Mount
  useEffect(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setFunctions(parsed);
        }
      }
    } catch (e) {
      console.error("Failed to load autosave", e);
    }
  }, []);

  // -- Autosave Logic --

  const persistToStorage = () => {
    let currentData = functionsRef.current;

    // If we have a live canvas, merge its state into the data before saving
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const activeId = activeIdRef.current;
        currentData = currentData.map(f => 
            f.id === activeId 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }

    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(currentData));
        setLastSaved(new Date());
    } catch (e) {
        console.error("Autosave failed", e);
    }
  };

  useEffect(() => {
    // Autosave every 5 seconds
    const interval = setInterval(persistToStorage, 5000);

    // Save on tab switch/hide
    const handleVisibilityChange = () => {
        if (document.hidden) persistToStorage();
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    // Save on close/refresh
    const handleBeforeUnload = () => {
        persistToStorage();
    };
    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVisibilityChange);
        window.removeEventListener("beforeunload", handleBeforeUnload);
        persistToStorage(); // Save on unmount
    };
  }, []);

  // -- Drag & Drop Logic --

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedType, x: relX, y: relY, functionId: draggedFuncId });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  // -- Data Management Logic --

  /**
   * Synchronously gathers the complete state of the project.
   * Merges the live Canvas state (ref) with the stored React state for other functions.
   */
  const getLatestFunctionsState = (): FunctionCircuit[] => {
    if (canvasRef.current) {
      const { components, wires } = canvasRef.current.getData();
      return functions.map(f => 
        f.id === activeFunctionId 
          ? { ...f, components: [...components], wires: [...wires] }
          : f
      );
    }
    return functions;
  };

  const saveCurrentState = () => {
    const updated = getLatestFunctionsState();
    setFunctions(updated);
    // Persist immediately on explicit state saves
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(updated));
        setLastSaved(new Date());
    } catch(e) {}
    return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    saveCurrentState();
    setSelectedComponent(null);
    setActiveFunctionId(id);
    setIsPlaying(false); // Pause when switching context
  };

  // -- Storage / File Operations --

  const handleQuickSave = () => {
    persistToStorage();
    setIsProjectMenuOpen(false);
  };

  const handleClearStorage = () => {
    if (confirm("Clear local saved data? This will not delete the current workspace until you reload.")) {
        localStorage.removeItem(LOCAL_STORAGE_KEY);
    }
    setIsProjectMenuOpen(false);
  };

  const downloadJSON = (data: any, filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportProject = () => {
    const data = getLatestFunctionsState();
    downloadJSON(data, `logicflow_project_${new Date().getTime()}.json`);
    setIsProjectMenuOpen(false);
  };

  const handleExportFunction = () => {
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const funcData: FunctionCircuit = {
            ...activeFunction,
            components,
            wires
        };
        downloadJSON(funcData, `${activeFunction.name.replace(/\s+/g, '_')}_function.json`);
    }
    setIsProjectMenuOpen(false);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
    setIsProjectMenuOpen(false);
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content);

            if (Array.isArray(parsed)) {
                // CASE 1: Full Project Import
                if (parsed.length > 0 && parsed[0].id && parsed[0].components) {
                    if (confirm("This will replace your current project. Continue?")) {
                        setFunctions(parsed);
                        setActiveFunctionId(parsed[0].id);
                        setSelectedComponent(null);
                        setIsPlaying(false);
                        // Save immediately
                        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(parsed));
                    }
                } else {
                    alert("Invalid Project File");
                }
            } else if (typeof parsed === 'object' && parsed.id && parsed.components) {
                // CASE 2: Single Function Import
                const newFunc = parsed as FunctionCircuit;
                const existing = functions.find(f => f.id === newFunc.id);
                if (existing) {
                    newFunc.id = crypto.randomUUID();
                    newFunc.name = `${newFunc.name} (Imported)`;
                }

                // Get current state before appending
                const currentData = getLatestFunctionsState();
                const newData = [...currentData, newFunc];

                setFunctions(newData);
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));

                alert(`Imported function: ${newFunc.name}`);
            } else {
                alert("Unknown file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse JSON file.");
        }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  // -- Modal / Creation --

  const openNewFunctionModal = () => {
    setNewFuncName("");
    setIsModalOpen(true);
  };

  const submitNewFunction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFuncName.trim()) return;

    saveCurrentState(); // Saves current state + writes to localStorage

    // We need to fetch latest from refs because saveCurrentState writes to functions state which is async
    // Actually saveCurrentState returns the updated object, so use that.
    const currentData = getLatestFunctionsState();

    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = {
      id: newId,
      name: newFuncName,
      components: [],
      wires: []
    };
    const nextState = [...currentData, newFunc];

    setFunctions(nextState);
    setActiveFunctionId(newId);
    setIsModalOpen(false);

    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') {
      alert("Cannot delete Main Circuit");
      return;
    }
    if (confirm("Are you sure you want to delete this function?")) {
      setFunctions(prev => {
        const next = prev.filter(f => f.id !== id);
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(next));
        return next;
      });
      if (activeFunctionId === id) {
        setActiveFunctionId('main');
      }
    }
  };

  // -- Property Editor --

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) {
          setTempLabel(comp.customLabel || (comp.type === ComponentType.INPUT_SWITCH ? "IN" : (comp.type === ComponentType.OUTPUT_LED ? "OUT" : "")));
      } else {
        setTempLabel("");
      }
  };

  const updateLabel = (val: string) => {
      setTempLabel(val);
      updateComponentProp({ customLabel: val });
  };

  const updateComponentProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileImport} 
        accept=".json" 
        className="hidden" 
      />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => {
          if (t === 'SELECT' || t === 'DELETE') {
            setSelectedTool(t);
          }
        }}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">

        {/* Top Toolbar / HUD */}
        <div 
            className="absolute top-4 left-4 right-4 md:h-14 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap md:flex-nowrap items-center justify-between px-4 z-10 border border-slate-200 pointer-events-auto py-2 md:py-0 gap-2"
            onPointerDown={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            onTouchStart={(e) => e.stopPropagation()}
        >

          <div className="flex items-center space-x-2 md:space-x-4">
             {/* Function Selector */}
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => switchToFunction(e.target.value)}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => (
                   <option key={f.id} value={f.id}>{f.name}</option>
                 ))}
               </select>

               <button 
                 onClick={openNewFunctionModal}
                 className="ml-2 w-8 h-8 flex items-center justify-center bg-blue-100 text-blue-600 rounded hover:bg-blue-200 text-lg font-bold touch-manipulation"
                 title="New Function"
               >
                 +
               </button>

               {activeFunctionId !== 'main' && (
                 <button 
                   onClick={() => deleteFunction(activeFunctionId)}
                   className="ml-1 w-8 h-8 flex items-center justify-center bg-red-100 text-red-500 rounded hover:bg-red-200 text-lg font-bold touch-manipulation"
                   title="Delete Function"
                 >
                   ×
                 </button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             {/* Playback Controls */}
             <div className="flex items-center space-x-2 mr-2 hidden sm:flex">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500' : 'bg-slate-300'}`}></span>
             </div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors touch-manipulation"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             {/* Project / Storage Menu */}
             <div className="relative">
                <button
                    onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)}
                    className="flex items-center space-x-1 px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors"
                >
                    <span>Project</span>
                    <span className="text-xs">▼</span>
                </button>

                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-64 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                         <div className="px-4 py-2 text-xs text-slate-400 font-mono border-b border-slate-50 mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Not saved yet'}
                         </div>
                        <button onClick={handleQuickSave} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">💾</span> Save Now
                        </button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={triggerFileUpload} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📂</span> Import File...
                        </button>
                        <button onClick={handleExportProject} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📦</span> Export Project (All)
                        </button>
                        <button onClick={handleExportFunction} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📄</span> Export Function (Active)
                        </button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={handleClearStorage} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center">
                            <span className="mr-2">🗑️</span> Clear Browser Data
                        </button>
                    </div>
                )}
                {/* Backdrop to close menu */}
                {isProjectMenuOpen && (
                    <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>
                )}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {/* Property Editor (Visible when Selected) */}
             {selectedComponent && (
                 <div className="flex items-center space-x-2 mr-2 flex-1 md:flex-none justify-center">
                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <span className="text-[10px] font-bold text-yellow-600 mr-2 uppercase whitespace-nowrap">Label</span>
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => updateLabel(e.target.value)}
                            className="bg-white border border-yellow-200 text-base px-2 py-1 rounded w-24 md:w-32 focus:outline-none focus:border-yellow-400 shadow-sm select-text"
                            placeholder="Name..."
                        />
                     </div>

                     {/* IC Port Side Selector (Only for I/O) */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED || selectedComponent.type === ComponentType.CLOCK) && (
                         <div className="flex items-center bg-blue-50 px-2 py-1 rounded border border-blue-200">
                            <span className="text-[10px] font-bold text-blue-600 mr-2 uppercase whitespace-nowrap">Pin Side</span>
                            <select 
                                value={selectedComponent.icPortSide || (selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.CLOCK ? 'right' : 'left')}
                                onChange={(e) => updateComponentProp({ icPortSide: e.target.value as any })}
                                className="bg-white border border-blue-200 text-sm px-2 py-1 rounded w-20 focus:outline-none focus:border-blue-400 shadow-sm"
                            >
                                <option value="top">Top</option>
                                <option value="bottom">Bottom</option>
                                <option value="left">Left</option>
                                <option value="right">Right</option>
                            </select>
                         </div>
                     )}
                 </div>
             )}

            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider hidden sm:inline">DELAY</span>
            <input 
              type="range" 
              min="5" 
              max="1000" 
              step="5"
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-24 h-4 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-900 touch-pan-x" 
            />
            <span className="text-xs text-slate-500 w-8 text-right font-mono hidden sm:inline">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={activeFunctionId}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={handlePendingDropHandled}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {draggedType === ComponentType.CUSTOM_IC ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}
              </span>
            </div>
          </div>
        )}

        {/* Modal Overlay */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden" onPointerDown={(e) => e.stopPropagation()}>
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100">
                <h3 className="font-bold text-slate-700">Create New Function</h3>
              </div>
              <form onSubmit={submitNewFunction} className="p-4">
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Function Name</label>
                <input 
                  autoFocus
                  type="text" 
                  value={newFuncName}
                  onChange={(e) => setNewFuncName(e.target.value)}
                  placeholder="e.g. Full Adder"
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4 text-base font-semibold text-slate-700 select-text"
                />
                <div className="flex justify-end space-x-2">
                  <button 
                    type="button"
                    onClick={() => setIsModalOpen(false)}
                    className="px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-100 rounded-lg transition-colors"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="px-4 py-2 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors"
                  >
                    Create
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useLayoutEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, Wire, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';
const LOCAL_STORAGE_ID_KEY = 'logicflow_active_id_v1';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false); // Default to Paused
  const [tickSpeed, setTickSpeed] = useState(50); 

  // -- Multi-Circuit (Function) State --
  // Initialize Synchronously from LocalStorage to prevent "Flash of Empty State" or Race Conditions
  const [functions, setFunctions] = useState<FunctionCircuit[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch (e) {
      console.error("Failed to load autosave", e);
    }
    return [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
  });

  const [activeFunctionId, setActiveFunctionId] = useState<string>(() => {
    try {
        const savedId = localStorage.getItem(LOCAL_STORAGE_ID_KEY);
        if (savedId) return savedId;
    } catch(e) {}
    return 'main';
  });

  // Validate activeFunctionId on mount/update (in case saved ID doesn't exist in saved functions)
  useLayoutEffect(() => {
    if (!functions.find(f => f.id === activeFunctionId)) {
        setActiveFunctionId(functions[0]?.id || 'main');
    }
  }, [functions, activeFunctionId]);

  // Version counter to force re-mounting of LogicCanvas when data is bulk-imported
  const [dataVersion, setDataVersion] = useState(0);

  // -- UI State --
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // -- Selection State for Editing --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Refs for Autosave (Access latest state in intervals/callbacks)
  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);

  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  // Helper to get active function data safely
  const activeFunction = functions.find(f => f.id === activeFunctionId) || functions[0];

  // -- Autosave Logic --

  const persistToStorage = () => {
    let currentData = functionsRef.current;

    // If we have a live canvas, merge its state into the data before saving
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const activeId = activeIdRef.current;
        currentData = currentData.map(f => 
            f.id === activeId 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }

    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(currentData));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeIdRef.current);
        setLastSaved(new Date());
    } catch (e) {
        console.error("Autosave failed", e);
    }
  };

  useEffect(() => {
    // Autosave every 5 seconds
    const interval = setInterval(persistToStorage, 5000);

    // Save on tab switch/hide
    const handleVisibilityChange = () => {
        if (document.hidden) persistToStorage();
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    // Save on close/refresh
    const handleBeforeUnload = () => {
        persistToStorage();
    };
    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVisibilityChange);
        window.removeEventListener("beforeunload", handleBeforeUnload);
        persistToStorage(); // Save on unmount
    };
  }, []);

  // -- Drag & Drop Logic --

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedType, x: relX, y: relY, functionId: draggedFuncId });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  // -- Data Management Logic --

  /**
   * Synchronously gathers the complete state of the project.
   * Merges the live Canvas state (ref) with the stored React state for other functions.
   */
  const getLatestFunctionsState = (): FunctionCircuit[] => {
    if (canvasRef.current) {
      const { components, wires } = canvasRef.current.getData();
      return functions.map(f => 
        f.id === activeFunctionId 
          ? { ...f, components: [...components], wires: [...wires] }
          : f
      );
    }
    return functions;
  };

  const saveCurrentState = () => {
    const updated = getLatestFunctionsState();
    setFunctions(updated);
    // Persist immediately on explicit state saves
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(updated));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeFunctionId);
        setLastSaved(new Date());
    } catch(e) {}
    return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    saveCurrentState();
    setSelectedComponent(null);
    setActiveFunctionId(id);
    setIsPlaying(false); // Pause when switching context
  };

  // -- Storage / File Operations --

  const handleQuickSave = () => {
    persistToStorage();
    setIsProjectMenuOpen(false);
  };

  const handleClearStorage = () => {
    if (confirm("Clear local saved data? This will reset the project.")) {
        localStorage.removeItem(LOCAL_STORAGE_KEY);
        localStorage.removeItem(LOCAL_STORAGE_ID_KEY);
        // Reset state
        const defaultState = [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
        setFunctions(defaultState);
        setActiveFunctionId('main');
        setDataVersion(v => v + 1); // Force canvas refresh
    }
    setIsProjectMenuOpen(false);
  };

  const downloadJSON = (data: any, filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportProject = () => {
    const data = getLatestFunctionsState();
    downloadJSON(data, `logicflow_project_${new Date().getTime()}.json`);
    setIsProjectMenuOpen(false);
  };

  const handleExportFunction = () => {
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const funcData: FunctionCircuit = {
            ...activeFunction,
            components,
            wires
        };
        downloadJSON(funcData, `${activeFunction.name.replace(/\s+/g, '_')}_function.json`);
    }
    setIsProjectMenuOpen(false);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
    setIsProjectMenuOpen(false);
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content);

            if (Array.isArray(parsed)) {
                // CASE 1: Full Project Import
                if (parsed.length > 0 && parsed[0].id && parsed[0].components) {
                    if (confirm("This will replace your current project. Continue?")) {
                        setFunctions(parsed);
                        setActiveFunctionId(parsed[0].id);
                        setSelectedComponent(null);
                        setIsPlaying(false);
                        setDataVersion(v => v + 1); // Force Canvas Remount

                        // Save immediately
                        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(parsed));
                        localStorage.setItem(LOCAL_STORAGE_ID_KEY, parsed[0].id);
                    }
                } else {
                    alert("Invalid Project File");
                }
            } else if (typeof parsed === 'object' && parsed.id && parsed.components) {
                // CASE 2: Single Function Import
                const newFunc = parsed as FunctionCircuit;
                const existing = functions.find(f => f.id === newFunc.id);
                if (existing) {
                    newFunc.id = crypto.randomUUID();
                    newFunc.name = `${newFunc.name} (Imported)`;
                }

                // Get current state before appending
                const currentData = getLatestFunctionsState();
                const newData = [...currentData, newFunc];

                setFunctions(newData);
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));
                // active ID doesn't change

                alert(`Imported function: ${newFunc.name}`);
            } else {
                alert("Unknown file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse JSON file.");
        }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  // -- Modal / Creation --

  const openNewFunctionModal = () => {
    setNewFuncName("");
    setIsModalOpen(true);
  };

  const submitNewFunction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFuncName.trim()) return;

    // Explicitly save first to ensure we don't lose current changes
    const currentData = saveCurrentState(); 

    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = {
      id: newId,
      name: newFuncName,
      components: [],
      wires: []
    };
    const nextState = [...currentData, newFunc];

    setFunctions(nextState);
    setActiveFunctionId(newId);
    setIsModalOpen(false);

    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));
    localStorage.setItem(LOCAL_STORAGE_ID_KEY, newId);
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') {
      alert("Cannot delete Main Circuit");
      return;
    }
    if (confirm("Are you sure you want to delete this function?")) {
      const nextState = functions.filter(f => f.id !== id);
      setFunctions(nextState);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));

      if (activeFunctionId === id) {
        setActiveFunctionId('main');
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, 'main');
      }
    }
  };

  // -- Property Editor --

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) {
          setTempLabel(comp.customLabel || (comp.type === ComponentType.INPUT_SWITCH ? "IN" : (comp.type === ComponentType.OUTPUT_LED ? "OUT" : "")));
      } else {
        setTempLabel("");
      }
  };

  const updateLabel = (val: string) => {
      setTempLabel(val);
      updateComponentProp({ customLabel: val });
  };

  const updateComponentProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileImport} 
        accept=".json" 
        className="hidden" 
      />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => {
          if (t === 'SELECT' || t === 'DELETE') {
            setSelectedTool(t);
          }
        }}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">

        {/* Top Toolbar / HUD */}
        <div 
            className="absolute top-4 left-4 right-4 md:h-14 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap md:flex-nowrap items-center justify-between px-4 z-10 border border-slate-200 pointer-events-auto py-2 md:py-0 gap-2"
            onPointerDown={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            onTouchStart={(e) => e.stopPropagation()}
        >

          <div className="flex items-center space-x-2 md:space-x-4">
             {/* Function Selector */}
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => switchToFunction(e.target.value)}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => (
                   <option key={f.id} value={f.id}>{f.name}</option>
                 ))}
               </select>

               <button 
                 onClick={openNewFunctionModal}
                 className="ml-2 w-8 h-8 flex items-center justify-center bg-blue-100 text-blue-600 rounded hover:bg-blue-200 text-lg font-bold touch-manipulation"
                 title="New Function"
               >
                 +
               </button>

               {activeFunctionId !== 'main' && (
                 <button 
                   onClick={() => deleteFunction(activeFunctionId)}
                   className="ml-1 w-8 h-8 flex items-center justify-center bg-red-100 text-red-500 rounded hover:bg-red-200 text-lg font-bold touch-manipulation"
                   title="Delete Function"
                 >
                   ×
                 </button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             {/* Playback Controls */}
             <div className="flex items-center space-x-2 mr-2 hidden sm:flex">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500' : 'bg-slate-300'}`}></span>
             </div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors touch-manipulation"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             {/* Project / Storage Menu */}
             <div className="relative">
                <button
                    onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)}
                    className="flex items-center space-x-1 px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors"
                >
                    <span>Project</span>
                    <span className="text-xs">▼</span>
                </button>

                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-64 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                         <div className="px-4 py-2 text-xs text-slate-400 font-mono border-b border-slate-50 mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Not saved yet'}
                         </div>
                        <button onClick={handleQuickSave} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">💾</span> Save Now
                        </button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={triggerFileUpload} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📂</span> Import File...
                        </button>
                        <button onClick={handleExportProject} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📦</span> Export Project (All)
                        </button>
                        <button onClick={handleExportFunction} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center">
                            <span className="mr-2">📄</span> Export Function (Active)
                        </button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={handleClearStorage} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center">
                            <span className="mr-2">🗑️</span> Clear Browser Data
                        </button>
                    </div>
                )}
                {/* Backdrop to close menu */}
                {isProjectMenuOpen && (
                    <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>
                )}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {/* Property Editor (Visible when Selected) */}
             {selectedComponent && (
                 <div className="flex items-center space-x-2 mr-2 flex-1 md:flex-none justify-center">
                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <span className="text-[10px] font-bold text-yellow-600 mr-2 uppercase whitespace-nowrap">Label</span>
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => updateLabel(e.target.value)}
                            className="bg-white border border-yellow-200 text-base px-2 py-1 rounded w-24 md:w-32 focus:outline-none focus:border-yellow-400 shadow-sm select-text"
                            placeholder="Name..."
                        />
                     </div>

                     {/* IC Port Side Selector (Only for I/O) */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED || selectedComponent.type === ComponentType.CLOCK) && (
                         <div className="flex items-center bg-blue-50 px-2 py-1 rounded border border-blue-200">
                            <span className="text-[10px] font-bold text-blue-600 mr-2 uppercase whitespace-nowrap">Pin Side</span>
                            <select 
                                value={selectedComponent.icPortSide || (selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.CLOCK ? 'right' : 'left')}
                                onChange={(e) => updateComponentProp({ icPortSide: e.target.value as any })}
                                className="bg-white border border-blue-200 text-sm px-2 py-1 rounded w-20 focus:outline-none focus:border-blue-400 shadow-sm"
                            >
                                <option value="top">Top</option>
                                <option value="bottom">Bottom</option>
                                <option value="left">Left</option>
                                <option value="right">Right</option>
                            </select>
                         </div>
                     )}
                 </div>
             )}

            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider hidden sm:inline">DELAY</span>
            <input 
              type="range" 
              min="5" 
              max="1000" 
              step="5"
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-24 h-4 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-900 touch-pan-x" 
            />
            <span className="text-xs text-slate-500 w-8 text-right font-mono hidden sm:inline">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={handlePendingDropHandled}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {draggedType === ComponentType.CUSTOM_IC ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}
              </span>
            </div>
          </div>
        )}

        {/* Modal Overlay */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden" onPointerDown={(e) => e.stopPropagation()}>
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100">
                <h3 className="font-bold text-slate-700">Create New Function</h3>
              </div>
              <form onSubmit={submitNewFunction} className="p-4">
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Function Name</label>
                <input 
                  autoFocus
                  type="text" 
                  value={newFuncName}
                  onChange={(e) => setNewFuncName(e.target.value)}
                  placeholder="e.g. Full Adder"
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4 text-base font-semibold text-slate-700 select-text"
                />
                <div className="flex justify-end space-x-2">
                  <button 
                    type="button"
                    onClick={() => setIsModalOpen(false)}
                    className="px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-100 rounded-lg transition-colors"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="px-4 py-2 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors"
                  >
                    Create
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;
